import pandas as pd
import numpy as np

# ── 1. Load data ──────────────────────────────────────────────────────────
df = pd.read_excel("/root/data.xlsx", sheet_name="Data", header=None)
data_start = 9

turns = df.iloc[data_start:, [2,3,4,5,6,7,8,9]].copy()
turns.columns = ['turn_number','game_number','r1','r2','r3','r4','r5','r6']
turns = turns.dropna(subset=['turn_number'])
turns = turns[pd.to_numeric(turns['turn_number'], errors='coerce').notna()]
turns = turns.astype(int)
print(f"Total turns: {len(turns)}")

# ── 2. Scoring functions ─────────────────────────────────────────────────
def score_high_and_often(rolls):
    mx = max(rolls)
    return mx * rolls.count(mx)

def score_summation(rolls):
    return sum(rolls)

def score_highs_and_lows(rolls):
    hi = max(rolls)
    lo = min(rolls)
    return hi * lo * (hi - lo)

def score_only_two_numbers(rolls):
    return 30 if len(set(rolls)) == 2 else 0

def score_all_the_numbers(rolls):
    return 40 if set(rolls) == {1,2,3,4,5,6} else 0

def score_ordered_four(rolls):
    n = len(rolls)
    for i in range(n - 3):
        inc = True
        dec = True
        for j in range(3):
            if rolls[i+j+1] != rolls[i+j] + 1:
                inc = False
            if rolls[i+j+1] != rolls[i+j] - 1:
                dec = False
        if inc or dec:
            return 50
    return 0

def all_scores(rolls):
    r = [int(x) for x in rolls]
    return [
        score_high_and_often(r),
        score_summation(r),
        score_highs_and_lows(r),
        score_only_two_numbers(r),
        score_all_the_numbers(r),
        score_ordered_four(r),
    ]

# ── 3. Compute scores for all turns, grouped by game ─────────────────────
game_turns = {}
for _, row in turns.iterrows():
    gn = int(row['game_number'])
    rolls = [int(row['r1']), int(row['r2']), int(row['r3']), int(row['r4']), int(row['r5']), int(row['r6'])]
    scores = all_scores(rolls)
    if gn not in game_turns:
        game_turns[gn] = []
    game_turns[gn].append(scores)

print(f"Total games: {len(game_turns)}")

# Check game 8
print(f"Game 8 has {len(game_turns[8])} turn(s)")
print(f"Game 8 scores: {game_turns[8]}")

# ── 4. Compute optimal game score ────────────────────────────────────────
def best_game_score_2turns(scores1, scores2):
    best = 0
    n = len(scores1)
    for c1 in range(n):
        for c2 in range(n):
            if c1 != c2:
                total = scores1[c1] + scores2[c2]
                if total > best:
                    best = total
    return best

def best_game_score_1turn(scores1):
    return max(scores1)

game_scores = {}
for gn in sorted(game_turns.keys()):
    t = game_turns[gn]
    if len(t) == 2:
        game_scores[gn] = best_game_score_2turns(t[0], t[1])
    elif len(t) == 1:
        game_scores[gn] = best_game_score_1turn(t[0])
        print(f"Warning: Game {gn} has only 1 turn, score = {game_scores[gn]}")
    else:
        print(f"Error: Game {gn} has {len(t)} turns!")

print(f"\nFirst 10 game scores: {[(g, game_scores[g]) for g in range(1,11)]}")

# ── 5. Player matching ───────────────────────────────────────────────────
p1_wins = 0
p2_wins = 0
draws = 0

for i in range(1, 3000, 2):
    g_odd = i      # Player 1
    g_even = i + 1  # Player 2

    p1_score = game_scores[g_odd]
    p2_score = game_scores[g_even]

    if p1_score > p2_score:
        p1_wins += 1
    elif p2_score > p1_score:
        p2_wins += 1
    else:
        draws += 1

print(f"\nPlayer 1 wins: {p1_wins}")
print(f"Player 2 wins: {p2_wins}")
print(f"Draws: {draws}")
print(f"Total matches: {p1_wins + p2_wins + draws}")
answer = p1_wins - p2_wins
print(f"\nAnswer (P1 wins - P2 wins): {answer}")

# Write answer
with open("/root/answer.txt", "w") as f:
    f.write(str(answer))
print(f"Answer written to /root/answer.txt")

PYEOF
